package com.vit.archds.controller; import com.vit.archds.dto.ProjectDtos.*; import com.vit.archds.entity.*; import com.vit.archds.service.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/projects") public class ProjectController { private final ProjectService projects; private final AnalysisService analysis; private final DecisionService decisions; public ProjectController(ProjectService p,AnalysisService a,DecisionService d){projects=p;analysis=a;decisions=d;}
 @GetMapping public List<ProjectResponse> list(){return projects.all().stream().map(this::dto).toList();}
 @PostMapping public ResponseEntity<ProjectResponse> create(@Valid @RequestBody CreateProject d){Project p=projects.create(d);return ResponseEntity.status(HttpStatus.CREATED).body(dto(p));}
 @GetMapping("/{id}") public ProjectResponse get(@PathVariable long id){return dto(projects.get(id));}
 @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable long id){projects.delete(id);}
 @PostMapping("/{id}/requirements") public ResponseEntity<Map<String,Object>> requirements(@PathVariable long id,@Valid @RequestBody Requirements d){Requirement r=projects.saveRequirements(id,d);return ResponseEntity.status(HttpStatus.CREATED).body(Map.of("id",r.getId(),"message","Requirements saved"));}
 @PostMapping("/{id}/run-analysis") public ResponseEntity<JobResponse> run(@PathVariable long id){return ResponseEntity.accepted().body(job(analysis.start(id)));}
 @GetMapping("/{id}/requirements") public Map<String,Object> requirements(@PathVariable long id){Requirement r=projects.latestRequirement(id);return Map.of("id",r.getId(),"functional_requirements",r.getFunctionalRequirements(),"non_functional_requirements",r.getNonFunctionalRequirements(),"constraints",r.getConstraints(),"technology_preferences",r.getTechnologyPreferences(),"expected_users",Objects.toString(r.getExpectedUsers(),""),"budget",Objects.toString(r.getBudget(),""),"quality_weights",r.getQualityWeightsJson(),"alternatives",r.getAlternatives(),"max_iterations",r.getMaxIterations());}
 @GetMapping("/{id}/analysis") public Object result(@PathVariable long id){return analysis.result(id);}
 @GetMapping("/{id}/history") public List<JobResponse> history(@PathVariable long id){return analysis.history(id).stream().map(this::job).toList();}
 @PostMapping("/{id}/decision") public Map<String,Object> decision(@PathVariable long id,@Valid @RequestBody DecisionRequest d){return decisions.record(id,d);}
 private ProjectResponse dto(Project p){return new ProjectResponse(p.getId(),p.getName(),p.getDescription(),p.getCreatedAt(),p.getUpdatedAt());} private JobResponse job(AnalysisJob j){return new JobResponse(j.getJobId(),j.getStatus().name(),j.getProgress(),j.getCurrentStage(),j.getMessage(),j.getErrorMessage(),j.getCreatedAt(),j.getStartedAt(),j.getCompletedAt());}}
